import raw from '@/data/hero-counters.json';

/**
 * Loader for the programmatic counter pages.
 *
 * The dataset is generated by `tools/pipeline/build_seo_pages.py` from the same
 * artifact the engine uses, so the numbers on these public pages always match
 * what the app itself would tell a player. Committing it keeps the pages
 * dependency-free at build time.
 */
export type SeoHeroRef = { id: number; name: string; slug: string; score: number };

export type SeoHero = {
  id: number;
  name: string;
  slug: string;
  roles: string[];
  icon: string | null;
  img: string | null;
  attr: string | null;
  pub_winrate: number;
  cm_winrate: number;
  counters: SeoHeroRef[];
  strong_against: SeoHeroRef[];
  problems: string[];
  good_items: { key: string; name: string }[];
  bad_items: { key: string; name: string }[];
};

type Data = { patch: string | null; heroes: Record<string, SeoHero> };

const data = raw as unknown as Data;

export const SEO_PATCH = data.patch;
export const allSeoHeroes = Object.values(data.heroes);

export function getSeoHero(slug: string): SeoHero | undefined {
  return data.heroes[slug];
}
